<?php
if(PHP_SAPI!=='cli')exit("CLI only\n");require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/behavior_analytics.php';$db=(new Database())->getConnection();$wall=microtime(true);$cpu0=getrusage();$rules=behaviorThresholds($db);$cases=$db->query("SELECT experiment_case_id,user_id,MIN(occurred_at) started_at,MAX(actual_label) actual_label FROM user_activity_logs WHERE source='simulation' GROUP BY experiment_case_id,user_id")->fetchAll();if(count($cases)!==3000)exit("Expected 3000 cases\n");$tp=$tn=$fp=$fn=0;$dt=$rt=[];$db->exec("DELETE FROM behavior_detections WHERE source='simulation'");$ins=$db->prepare("INSERT INTO behavior_detections(user_id,feature_code,window_started_at,window_ended_at,observed_value,threshold_value,predicted_label,actual_label,detection_time_ms,action_taken,source) VALUES(?,?,?,?,?,?,?,?,?,'experiment_only','simulation')");
foreach($cases as$c){$q=$db->prepare("SELECT * FROM user_activity_logs WHERE source='simulation' AND experiment_case_id=? ORDER BY occurred_at,id");$q->execute([$c['experiment_case_id']]);$logs=$q->fetchAll();$max=array_fill_keys(array_keys($rules),0);$attack=$detected=null;$hit='';foreach($logs as$a){$t=strtotime($a['occurred_at']);$rt[]=(float)$a['response_time_ms'];if($c['actual_label']==='suspicious'&&$attack===null&&($a['action']==='login.failed'||(int)$a['request_count']>50||$a['action']==='order.created'))$attack=$t;$v=['login_per_min'=>0,'request_per_min'=>0,'order_per_hour'=>0,'failed_login_per_10min'=>0];foreach($logs as$x){$xt=strtotime($x['occurred_at']);if($xt>$t)continue;if($xt>$t-60&&in_array($x['action'],['login.success','login.failed'],true))$v['login_per_min']++;if($xt>$t-60&&$x['action']==='request')$v['request_per_min']+=(int)$x['request_count'];if($xt>$t-3600&&$x['action']==='order.created')$v['order_per_hour']++;if($xt>$t-600&&$x['action']==='login.failed')$v['failed_login_per_10min']++;}foreach($v as$k=>$n){$max[$k]=max($max[$k],$n);if($detected===null&&$n>(float)$rules[$k]['threshold_value']){$detected=$t;$hit=$k;}}}$actual=$c['actual_label'];$pred=$detected===null?'normal':'suspicious';if($actual==='suspicious'&&$pred==='suspicious')$tp++;elseif($actual==='normal'&&$pred==='normal')$tn++;elseif($actual==='normal')$fp++;else$fn++;if($detected!==null){$ms=$actual==='suspicious'?max(0,($detected-($attack??$detected))*1000):0;if($actual==='suspicious')$dt[]=$ms;$ins->execute([(int)$c['user_id'],$hit,$c['started_at'],date('Y-m-d H:i:s',$detected),$max[$hit],(float)$rules[$hit]['threshold_value'],$pred,$actual,$ms]);}}
function z($a,$b){return$b?$a/$b:0;}function p95(array$a){if(!$a)return 0;sort($a);return(float)$a[(int)floor((count($a)-1)*.95)];}$accuracy=z($tp+$tn,3000);$precision=z($tp,$tp+$fp);$recall=z($tp,$tp+$fn);$f1=z(2*$precision*$recall,$precision+$recall);$fpr=z($fp,$fp+$tn);$elapsed=max(.001,microtime(true)-$wall);$c1=getrusage();$cpu=((($c1['ru_utime.tv_sec']-$cpu0['ru_utime.tv_sec'])*1e6)+$c1['ru_utime.tv_usec']-$cpu0['ru_utime.tv_usec'])/1000;$cpuPct=min(100,$cpu/($elapsed*10));$avgD=z(array_sum($dt),count($dt));$avgR=z(array_sum($rt),count($rt));$perf=['avg_detection_ms'=>$avgD,'p95_detection_ms'=>p95($dt),'avg_response_ms'=>$avgR,'p95_response_ms'=>p95($rt),'throughput_cases_sec'=>3000/$elapsed,'cpu_ms'=>$cpu,'cpu_usage_percent'=>$cpuPct,'peak_memory_mb'=>memory_get_peak_usage(true)/1048576];$report=['confusion_matrix'=>compact('tp','tn','fp','fn'),'metrics'=>compact('accuracy','precision','recall','f1','fpr'),'performance'=>$perf];$code='EXP-'.date('Ymd-His');$s=$db->prepare('INSERT INTO behavior_experiments(run_code,user_count,observation_days,total_cases,true_positive,true_negative,false_positive,false_negative,accuracy,precision_score,recall_score,f1_score,false_positive_rate,avg_detection_time_ms,p95_detection_time_ms,avg_response_time_ms,p95_response_time_ms,throughput_cases_sec,cpu_time_ms,cpu_usage_percent,peak_memory_mb,report_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$code,100,30,3000,$tp,$tn,$fp,$fn,$accuracy,$precision,$recall,$f1,$fpr,$avgD,$perf['p95_detection_ms'],$avgR,$perf['p95_response_ms'],$perf['throughput_cases_sec'],$cpu,$cpuPct,$perf['peak_memory_mb'],json_encode($report)]);echo json_encode(['run_code'=>$code]+$report,JSON_PRETTY_PRINT)."\n";
